import {expect} from '@playwright/test';
import {randomUUID} from 'node:crypto';
import {invertCube} from './lut-ui.mjs';
import {imageDigest} from './text-ui.mjs';
export async function exerciseLutFolds(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh,prefix='Fold-'+randomUUID().slice(0,8),names=['A','B','C','D'].map(n=>prefix+n+'.cube'),panel=page.locator('.lut-panel'),image=page.locator('.edit-image img'),sourceName=await image.getAttribute('alt');
 await panel.locator(':scope>summary').click();await panel.getByRole('combobox',{name:t('样式分组','Style group'),exact:true}).selectOption('all');await panel.getByRole('searchbox').fill(prefix);
 await panel.locator('input[type=file]').first().setInputFiles(names.map(name=>({name,mimeType:'application/octet-stream',buffer:Buffer.from(invertCube(name))})));await expect(panel.locator('.lut-import-report')).toContainText(t('新增 4','Added 4'));
 const choice=i=>panel.getByRole('button',{name:t('应用 LUT ','Apply LUT ')+names[i],exact:true}),header=g=>panel.locator(`[data-lut-group=${g}]>button`),expand=panel.getByRole('button',{name:t('展开全部分组','Expand all groups'),exact:true});await expand.click();
 await panel.getByRole('button',{name:t('收藏 LUT ','Favorite LUT ')+names[0],exact:true}).click();const sourceDigest=await imageDigest(image);await choice(1).click();await expect.poll(()=>imageDigest(image)).not.toBe(sourceDigest);await panel.getByRole('button',{name:t('刷新样式','Refresh styles'),exact:true}).click();await expect(header('recent')).toBeVisible();const graded=await imageDigest(image);
 await header('recent').focus();await page.keyboard.press('Enter');await expect(header('recent')).toHaveAttribute('aria-expanded','false');await expect(header('recent')).toBeFocused();await expect(choice(1)).toHaveCount(0);await expect.poll(()=>imageDigest(image)).toBe(graded);
 await panel.getByRole('combobox',{name:t('缩略图列数','Thumbnail columns'),exact:true}).selectOption('2');await choice(0).focus();await page.keyboard.press('ArrowDown');await expect(choice(2)).toBeFocused();await page.keyboard.press('Escape');await expect(panel.getByRole('button',{name:t('移除当前 LUT','Clear current LUT'),exact:true})).toBeVisible();
 await header('favorite').click();await expect(choice(0)).toHaveCount(0);await expect(header('recent')).toHaveAttribute('aria-expanded','false');await panel.getByRole('searchbox').fill(names[0]);await expect(header('favorite')).toHaveAttribute('aria-expanded','false');await expect(panel).not.toContainText(t('暂无匹配样式。','No matching styles.'));await header('favorite').click();await expect(choice(0)).toBeVisible();await header('favorite').click();await panel.getByRole('searchbox').fill(prefix);
 const save=page.getByRole('button',{name:new RegExp('^'+t('保存编辑','Save edits'))});await save.click();await expect(save).toBeEnabled();await page.goto(await page.evaluate(()=>document.documentElement.dataset.runtime==='browser')?'/#/tools/edit':'/tools/darkroom');await page.reload();await page.locator('.edit-records>div>button').filter({hasText:sourceName}).first().click();await expect.poll(()=>imageDigest(image)).toBe(graded);await panel.locator(':scope>summary').click();await panel.getByRole('searchbox').fill(prefix);await expect(header('favorite')).toHaveAttribute('aria-expanded','false');await expect(header('recent')).toHaveAttribute('aria-expanded','false');await expect(choice(0)).toHaveCount(0);await expect(choice(1)).toHaveCount(0);
 await panel.getByRole('button',{name:t('收起全部分组','Collapse all groups'),exact:true}).click();await expect(panel.locator('.lut-choice')).toHaveCount(0);await expect(panel.locator('.lut-group-heading')).toHaveCount(3);await header('other').focus();await page.keyboard.press('Space');await expect(choice(2)).toBeVisible();await expect(header('other')).toBeFocused();await expect.poll(()=>imageDigest(image)).toBe(graded);
 await panel.locator('.lut-list').screenshot({path:info.outputPath('lut-folds.png')});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);if(lang==='en')expect(await panel.innerText()).not.toMatch(/[\u3400-\u9fff]/);await expand.click();await expect(panel.locator('.lut-choice')).toHaveCount(4);
}
